from pylint.testutils import CheckerTestCase, MessageTest
from pylint.extensions.eq_without_hash import EqWithoutHash
from pylint.interfaces import HIGH


class TestVisitClassdef(CheckerTestCase):
    CHECKER_CLASS = EqWithoutHash

    def _get_node(self, code):
        """Helper method to parse code and get the class node."""
        module = astroid.parse(code)
        return module.body[0]

    def test_class_with_eq_without_hash(self):
        """Test that a class with __eq__ but without __hash__ triggers the warning."""
        class_code = """
class MyClass:
    def __eq__(self, other):
        return True
"""
        class_node = self._get_node(class_code)
        with self.assertAddsMessages(
            MessageTest(
                msg_id="eq-without-hash",
                node=class_node,
                confidence=HIGH,
                line=2,
                col_offset=0,
            )
        ):
            self.checker.visit_classdef(class_node)

    def test_class_with_eq_and_hash(self):
        """Test that a class with both __eq__ and __hash__ does not trigger the warning."""
        class_code = """
class MyClass:
    def __eq__(self, other):
        return True

    def __hash__(self):
        return hash(id(self))
"""
        class_node = self._get_node(class_code)
        with self.assertNoMessages():
            self.checker.visit_classdef(class_node)

    def test_class_without_eq(self):
        """Test that a class without __eq__ does not trigger the warning."""
        class_code = """
class MyClass:
    def some_method(self):
        pass
"""
        class_node = self._get_node(class_code)
        with self.assertNoMessages():
            self.checker.visit_classdef(class_node)

    def test_class_with_hash_without_eq(self):
        """Test that a class with only __hash__ does not trigger the warning."""
        class_code = """
class MyClass:
    def __hash__(self):
        return hash(id(self))
"""
        class_node = self._get_node(class_code)
        with self.assertNoMessages():
            self.checker.visit_classdef(class_node)

    def test_inherited_eq_without_hash(self):
        """Test that a class inheriting __eq__ without __hash__ triggers the warning."""
        class_code = """
class Base:
    def __eq__(self, other):
        return True

class Derived(Base):
    pass
"""
        module = astroid.parse(class_code)
        derived_class_node = module.body[1]
        # The checker should detect that Derived inherits __eq__ from Base
        # but doesn't have __hash__, so it should trigger the warning
        with self.assertAddsMessages(
            MessageTest(
                msg_id="eq-without-hash",
                node=derived_class_node,
                confidence=HIGH,
                line=6,
                col_offset=0,
            )
        ):
            self.checker.visit_classdef(derived_class_node)

